<script setup lang="ts">
import { computed, onUnmounted, reactive, ref, watch } from 'vue'
import { api, type Definition } from '../api'
import { ApprovalOperationsQuery, defaultOperationsFilter, operationsDuration, operationsFilter, type OperationsProcess } from '../approvalOperations'

const props = defineProps<{ scopeKey: string; refreshVersion: number; definitions: Definition[] }>()
const emit = defineEmits<{ open: [applicationId: string] }>()
const query = reactive(new ApprovalOperationsQuery(api.approvalOperations))
const initial = defaultOperationsFilter()
const filters = reactive({ from: initial.from, to: initial.to, processKey: '', version: '' })
const inputError = ref('')
const report = computed(() => query.report)
const processes = computed(() => [...new Map(props.definitions.map(item => [item.key, item.name])).entries()].sort(([a], [b]) => a.localeCompare(b)))
const trendMax = computed(() => Math.max(1, ...(report.value?.daily.map(day => day.submittedRounds) ?? [])))
const number = (value: number) => new Intl.NumberFormat('zh-CN').format(value)
const percent = (value?: number) => value == null ? '—' : value.toFixed(1) + '%'
const time = (value: string) => new Date(value).toLocaleString('zh-CN')
const outcomes = computed(() => report.value ? [
  { label: '已批准', value: report.value.metrics.approved, color: 'approved' },
  { label: '已退回', value: report.value.metrics.returned, color: 'returned' },
  { label: '已驳回', value: report.value.metrics.rejected, color: 'rejected' },
  { label: '已撤回', value: report.value.metrics.withdrawn, color: 'withdrawn' }
] : [])
function refresh() {
  inputError.value = ''
  try { void query.load(props.scopeKey, operationsFilter(filters.from, filters.to, filters.processKey, filters.version)) }
  catch (cause) { query.clear(); inputError.value = (cause as Error).message }
}
function reset() { Object.assign(filters, defaultOperationsFilter(), { processKey: '', version: '' }); refresh() }
function chooseDay(date: string) { filters.from = date; filters.to = date; refresh() }
function chooseProcess(process: OperationsProcess) { filters.processKey = process.processKey; filters.version = String(process.definitionVersion); refresh() }
watch(filters, () => { query.clear(); inputError.value = '' }, { flush: 'sync' })
watch([() => props.scopeKey, () => props.refreshVersion], refresh, { immediate: true, flush: 'sync' })
onUnmounted(() => query.clear())
</script>

<template>
  <section class="content operations" :aria-busy="query.loading">
    <div class="page-heading"><div><p class="eyebrow">OPERATIONS / APPROVALS</p><h2>审批运营</h2><p class="subhead">看提交与结论，也看仍在等待的审批。</p></div><button class="secondary" :disabled="query.loading" @click="refresh">{{ query.loading ? '正在统计…' : '刷新报告' }}</button></div>
    <form class="panel operations-filters" aria-label="统计筛选" @submit.prevent="refresh">
      <label>开始日期（UTC）<input v-model="filters.from" type="date" required /></label>
      <label>结束日期（UTC）<input v-model="filters.to" type="date" required /></label>
      <label class="process-filter">流程<select v-model="filters.processKey" @change="filters.version = ''"><option value="">全部流程</option><option v-if="filters.processKey && !processes.some(([key]) => key === filters.processKey)" :value="filters.processKey">{{ filters.processKey }}</option><option v-for="[key,name] in processes" :key="key" :value="key">{{ name }} · {{ key }}</option></select></label>
      <label class="version-filter">版本<input v-model="filters.version" type="number" min="1" step="1" max="2147483647" :disabled="!filters.processKey" placeholder="全部" /></label>
      <div class="operations-filter-actions"><button class="primary" :disabled="query.loading">查询统计</button><button class="quiet" type="button" @click="reset">重置近 30 天</button></div>
    </form>
    <p v-if="inputError" class="operations-error" role="alert">{{ inputError }}</p>
    <div v-if="query.loading" class="panel operations-empty" role="status"><strong>正在读取真实审批数据</strong><p>汇总提交轮次，并检查当前待办。</p></div>
    <div v-else-if="query.error" class="panel operations-empty" role="alert"><strong>未取得统计报告</strong><p>{{ query.error }}</p><button class="secondary" @click="refresh">重试查询</button></div>
    <template v-else-if="report">
      <div class="operations-scope"><p><strong>{{ report.from }} — {{ report.to }}</strong> · UTC 提交日期 · {{ report.processKey || '全部流程' }}{{ report.definitionVersion ? ' / v' + report.definitionVersion : '' }}</p><span>查询于 {{ time(report.generatedAt) }}</span></div>
      <div v-if="report.unrecordedHistoricalRounds" class="operations-warning" role="status">此流程范围有 {{ number(report.unrecordedHistoricalRounds) }} 个历史轮次缺少快照，无法确定提交日期，未计入以下轮次指标。</div>
      <div class="operations-metrics">
        <article><span>提交轮次</span><strong>{{ number(report.metrics.submittedRounds) }}</strong><p>涉及 {{ number(report.metrics.applications) }} 份申请，重提另计一轮</p></article>
        <article><span>窗口内仍在审批</span><strong>{{ number(report.metrics.inApproval) }}</strong><p>上述日期提交、当前尚未结束的轮次</p></article>
        <article><span>退回率</span><strong>{{ percent(report.metrics.returnRatePercent) }}</strong><p>{{ number(report.metrics.returned) }} 次退回 / {{ number(report.metrics.decidedRounds) }} 个审批结论，排除撤回</p></article>
        <article><span>已批准轮次平均用时</span><strong class="duration-metric">{{ operationsDuration(report.metrics.averageApprovalSeconds) }}</strong><p>{{ number(report.metrics.durationSamples) }} 个有效样本，含非工作时间</p></article>
      </div>
      <div class="operations-analysis">
        <section class="panel operations-trend" aria-labelledby="operations-trend-title"><div class="operations-section-heading"><h3 id="operations-trend-title">每日提交</h3><span>点击柱条查看该日</span></div>
          <div v-if="!report.metrics.submittedRounds" class="operations-empty"><strong>该日期范围内没有提交轮次</strong><p>调整筛选，或先完成一份申请的提交。</p></div>
          <div v-else class="trend-scroll"><div class="trend-bars" :style="{ gridTemplateColumns: `repeat(${report.daily.length}, minmax(14px, 1fr))` }"><button v-for="(day,index) in report.daily" :key="day.date" type="button" :aria-label="`${day.date} 提交 ${day.submittedRounds} 轮，查看该日`" :title="`${day.date} · ${number(day.submittedRounds)} 轮`" @click="chooseDay(day.date)"><span class="trend-column" :style="{ height: `${day.submittedRounds / trendMax * 160}px` }"></span><small>{{ index % Math.max(1, Math.ceil(report.daily.length / 6)) === 0 || index === report.daily.length - 1 ? day.date.slice(5) : '' }}</small></button></div></div>
          <p class="operations-help">按 UTC 提交日期计数；同一申请的补正重提会形成新的提交轮次。</p>
        </section>
        <section class="panel operations-outcomes" aria-labelledby="operations-outcomes-title"><div class="operations-section-heading"><h3 id="operations-outcomes-title">这些轮次的当前结论</h3></div><dl><div v-for="outcome in outcomes" :key="outcome.label"><dt><i :class="outcome.color"></i>{{ outcome.label }}</dt><dd>{{ number(outcome.value) }}</dd></div></dl><p class="operations-help">结论属于所选日期提交的轮次，可能在窗口结束后才作出。无审批结论时，退回率显示“—”。</p></section>
      </div>
      <section class="panel operations-panel" aria-labelledby="operations-process-title"><div class="operations-section-heading"><div><h3 id="operations-process-title">流程版本汇总</h3><p>按提交量排列，点击流程限定当前报告。</p></div><span v-if="report.moreProcesses">仅展示前 50 个版本</span></div><div v-if="report.processes.length" class="operations-table-scroll"><table><thead><tr><th scope="col">流程 / 版本</th><th scope="col">提交</th><th scope="col">在审</th><th scope="col">退回率</th><th scope="col">批准平均用时</th></tr></thead><tbody><tr v-for="process in report.processes" :key="process.processKey + ':' + process.definitionVersion"><th scope="row"><button class="operations-link" @click="chooseProcess(process)">{{ process.processKey }} <small>v{{ process.definitionVersion }}</small></button></th><td>{{ number(process.metrics.submittedRounds) }}</td><td>{{ number(process.metrics.inApproval) }}</td><td>{{ percent(process.metrics.returnRatePercent) }}</td><td>{{ operationsDuration(process.metrics.averageApprovalSeconds) }}</td></tr></tbody></table></div><p v-else class="operations-help">暂无匹配流程版本。</p></section>
      <div class="operations-backlog-heading"><div><p class="eyebrow">LIVE BACKLOG</p><h3>当前积压 <span>{{ number(report.pendingTasks) }} 项待办</span></h3><p>只受流程及版本筛选影响，不受上面的提交日期限制。会签每位成员各计一项任务。</p></div></div>
      <section class="panel operations-panel" aria-labelledby="operations-nodes-title"><div class="operations-section-heading"><h3 id="operations-nodes-title">等待最久的节点</h3><span v-if="report.moreWaitingNodes">前 20 项</span></div><div v-if="report.waitingNodes.length" class="operations-table-scroll"><table><thead><tr><th scope="col">节点</th><th scope="col">流程 / 版本</th><th scope="col">待办数</th><th scope="col">最长等待</th></tr></thead><tbody><tr v-for="node in report.waitingNodes" :key="`${node.processKey}:${node.definitionVersion}:${node.nodeId}:${node.nodeName}`"><th scope="row">{{ node.nodeName }}<small>{{ node.nodeId }}</small></th><td>{{ node.processKey }} / v{{ node.definitionVersion }}</td><td>{{ number(node.tasks) }}</td><td>{{ operationsDuration(node.oldestWaitSeconds) }}</td></tr></tbody></table></div><p v-else class="operations-help">当前流程范围没有待办积压。</p></section>
      <section class="panel operations-panel" aria-labelledby="operations-tasks-title"><div class="operations-section-heading"><div><h3 id="operations-tasks-title">优先关注的待办</h3><p>从任务创建起计算等待时间，委派回交不会重新计时。</p></div><span v-if="report.moreOldestTasks">前 20 项</span></div><article v-for="task in report.oldestTasks" :key="task.taskId" class="operations-task"><div><strong>{{ task.title }}</strong><p>{{ task.businessNo }} · {{ task.taskName }} · 第 {{ task.roundNo }} 轮</p><small>{{ task.assignee ? '当前处理人 ' + task.assignee : '等待候选人办理' }} · {{ time(task.createdAt) }} 进入待办</small></div><span>{{ operationsDuration(task.waitingSeconds) }}</span><button class="secondary" @click="emit('open', task.applicationId)">查看申请</button></article><p v-if="!report.oldestTasks.length" class="operations-help">暂无等待中的审批任务。</p></section>
      <details class="operations-boundaries"><summary>统计口径与尚未接入的指标</summary><p>提交量和结论读取提交轮次快照，不用当前申请状态覆盖旧轮次。退回率分母仅为批准、退回、驳回轮次；平均用时仅取已批准且时间有效的轮次，包含等待、周末和节假日。旧轮次缺失与时间无效的样本不会补造。</p><p>SLA 违约、外部通知投递失败、Agent 人工采纳率尚未接入，当前不提供这些指标的数值。等待较久表示需要关注，不等同于已违反 SLA。</p></details>
    </template>
    <div v-else-if="!inputError" class="panel operations-empty"><strong>筛选已改变</strong><p>点击“查询统计”取得对应范围的报告。</p></div>
  </section>
</template>

<style scoped>
.operations-filters{display:flex;align-items:end;flex-wrap:wrap;gap:14px;padding:20px}.operations-filters label{display:grid;gap:8px;font-size:11px;color:var(--muted);min-width:145px}.operations-filters input,.operations-filters select{height:39px;max-width:100%;min-width:0;border:1px solid var(--line);border-radius:6px;padding:8px 10px;background:#fff;font:inherit;color:var(--ink)}.operations-filters .process-filter{flex:1;min-width:230px;max-width:430px}.operations-filters .version-filter{min-width:85px;width:90px}.operations-filter-actions{display:flex;gap:10px;align-items:center}.operations-filter-actions button{font-size:12px;white-space:nowrap}.operations-scope{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;color:var(--muted);font-size:11px;margin:22px 0 16px;line-height:1.8}.operations-scope p{margin:0;overflow-wrap:anywhere}.operations-scope strong{color:var(--ink);font-weight:500}.operations-warning{font-size:12px;line-height:1.8;padding:14px 18px;border:1px solid #eadbb8;border-radius:9px;background:#fff9eb;color:#78622e;margin-bottom:18px}.operations-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin-bottom:22px}.operations-metrics article{background:white;border:1px solid var(--line);border-radius:10px;padding:22px}.operations-metrics article>span{font-size:12px;color:var(--muted)}.operations-metrics strong{display:block;font-size:34px;line-height:1.4;font-weight:600;color:var(--deep);font-variant-numeric:tabular-nums;margin:8px 0}.operations-metrics .duration-metric{font-size:24px;min-height:48px;display:flex;align-items:center;flex-wrap:wrap;overflow-wrap:anywhere}.operations-metrics p{margin:0;color:var(--muted);font-size:11px;line-height:1.8}.operations-analysis{display:grid;grid-template-columns:minmax(0,2fr) minmax(250px,1fr);gap:22px;margin-bottom:22px}.operations-trend,.operations-outcomes,.operations-panel{padding:23px}.operations-section-heading{display:flex;justify-content:space-between;align-items:start;gap:12px;margin-bottom:20px}.operations-section-heading h3{font-size:15px;margin:0}.operations-section-heading>span,.operations-section-heading p{font-size:11px;color:var(--muted);margin:7px 0 0;line-height:1.7}.operations-section-heading>span{margin:0;white-space:nowrap}.operations-help{font-size:11px;color:var(--muted);line-height:1.9}.trend-scroll{overflow-x:auto;padding-bottom:8px}.trend-bars{display:grid;align-items:end;min-height:190px;gap:5px}.trend-bars button{height:188px;display:flex;justify-content:end;align-items:center;flex-direction:column;gap:9px;padding:0;background:transparent;border:0;min-width:0}.trend-column{display:block;width:75%;min-height:2px;border-radius:4px 4px 0 0;background:var(--teal,#50aaa0);transition:background .15s}.trend-bars button:hover .trend-column{background:var(--deep)}.trend-bars button:focus-visible{outline:2px solid var(--deep);outline-offset:1px}.trend-bars small{font-size:9px;color:var(--muted);height:14px;white-space:nowrap}.operations-outcomes dl{margin:0}.operations-outcomes dl>div{display:flex;justify-content:space-between;padding:13px 0;border-bottom:1px solid var(--line);font-size:12px}.operations-outcomes dt{display:flex;align-items:center;gap:9px;color:var(--muted)}.operations-outcomes dd{margin:0;font-variant-numeric:tabular-nums;font-weight:600}.operations-outcomes i{height:7px;width:7px;border-radius:50%;background:#95a4aa}.operations-outcomes i.approved{background:#4b9a86}.operations-outcomes i.returned{background:#b78d42}.operations-outcomes i.rejected{background:#b46464}.operations-panel{margin-bottom:22px}.operations-table-scroll{overflow-x:auto}.operations table{width:100%;border-collapse:collapse;text-align:left;font-size:12px}.operations th,.operations td{padding:14px 12px;border-bottom:1px solid var(--line);line-height:1.8;vertical-align:top}.operations th:first-child,.operations td:first-child{padding-left:0}.operations thead th{color:var(--muted);font-size:11px;font-weight:400;white-space:nowrap}.operations tbody th{font-weight:500;max-width:360px;overflow-wrap:anywhere}.operations td{font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.operations th small{display:block;color:var(--muted);font-size:10px;font-weight:400}.operations-link{color:var(--deep);text-align:left;font:inherit;padding:0;overflow-wrap:anywhere}.operations-link:hover{text-decoration:underline}.operations-backlog-heading{margin:35px 0 20px}.operations-backlog-heading h3{font-size:23px;margin:9px 0}.operations-backlog-heading h3 span{font-size:14px;color:var(--deep);margin-left:12px}.operations-backlog-heading p:not(.eyebrow){font-size:12px;line-height:1.8;color:var(--muted)}.operations-task{display:flex;align-items:center;gap:20px;border-top:1px solid var(--line);padding:18px 0;font-size:12px}.operations-task>div{flex:1;min-width:0}.operations-task strong{font-size:13px;overflow-wrap:anywhere}.operations-task p,.operations-task small{font-size:11px;color:var(--muted);line-height:1.8;overflow-wrap:anywhere}.operations-task p{margin:7px 0}.operations-task>span{font-variant-numeric:tabular-nums;color:var(--deep);white-space:nowrap}.operations-task>button{font-size:11px;white-space:nowrap}.operations-empty{padding:44px 20px;text-align:center;font-size:14px}.operations-empty p{font-size:12px;line-height:1.8;color:var(--muted)}.operations-error{font-size:12px;color:var(--red);line-height:1.8}.operations-boundaries{padding:5px 0 25px;color:var(--muted);font-size:12px;line-height:1.9}.operations-boundaries summary{cursor:pointer;color:var(--ink)}
@media(max-width:1100px){.operations-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.operations-analysis{grid-template-columns:minmax(0,1fr)}.operations-outcomes dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:25px}}
@media(max-width:650px){.operations .page-heading{align-items:start;gap:15px;flex-direction:column}.operations-filters{padding:17px;gap:12px}.operations-filters label{width:calc(50% - 6px);min-width:0}.operations-filters .process-filter{max-width:none;min-width:0;flex-basis:100%}.operations-filters .version-filter{width:85px}.operations-metrics{gap:10px}.operations-metrics article{padding:17px 14px}.operations-metrics strong{font-size:28px}.operations-metrics .duration-metric{font-size:19px;min-height:39px}.operations-panel,.operations-trend,.operations-outcomes{padding:18px 15px}.operations table{min-width:550px}.operations-section-heading{flex-wrap:wrap}.operations-backlog-heading h3 span{display:block;margin:10px 0 0}.operations-task{flex-wrap:wrap;gap:12px}.operations-task>div{flex-basis:100%}.operations-task>button{margin-left:auto}.operations-scope{gap:3px}}
</style>
